module photo_validator (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] length,\n    input wire [127:0] packed_arr,\n    output reg result,\n    output reg done\n);\n\n    localparam [2:0] IDLE        = 3'd0;\n    localparam [2:0] INIT_I      = 3'd1;\n    localparam [2:0] CHECK_LEFT  = 3'd2;\n    localparam [2:0] CHECK_RIGHT = 3'd3;\n    localparam [2:0] FOUND_VALID = 3'd4;\n    localparam [2:0] DONE_STATE  = 3'd5;\n\n    reg [2:0] state;\n    reg [3:0] i, j, k;\n    reg [3:0] captured_len;\n    reg [127:0] captured_arr;\n    reg left_found;\n    reg [7:0] left_min_above;\n    reg right_found;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 1'b0;\n            done <= 1'b0;\n            i <= 4'd0;\n            j <= 4'd0;\n            k <= 4'd0;\n            left_found <= 1'b0;\n            left_min_above <= 8'hFF;\n            right_found <= 1'b0;\n            captured_len <= 4'd0;\n            captured_arr <= 128'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 1'b0;\n                    if (start) begin\n                        captured_arr <= packed_arr;\n                        captured_len <= length;\n                        i <= 4'd0;\n                        state <= INIT_I;\n                    end\n                end\n\n                INIT_I: begin\n                    if (i >= captured_len) begin\n                        result <= 1'b0;\n                        done <= 1'b1;\n                        state <= DONE_STATE;\n                    end else begin\n                        left_found <= 1'b0;\n                        left_min_above <= 8'hFF;\n                        j <= 4'd0;\n                        state <= CHECK_LEFT;\n                    end\n                end\n\n                CHECK_LEFT: begin\n                    if (j < i) begin\n                        if (captured_arr[j*8 +: 8] > captured_arr[i*8 +: 8]) begin\n                            left_found <= 1'b1;\n                            if (captured_arr[j*8 +: 8] < left_min_above) begin\n                                left_min_above <= captured_arr[j*8 +: 8];\n                            end\n                        end\n                        j <= j + 4'd1;\n                    end else begin\n                        if (left_found) begin\n                            k <= i + 4'd1;\n                            right_found <= 1'b0;\n                            state <= CHECK_RIGHT;\n                        end else begin\n                            i <= i + 4'd1;\n                            state <= INIT_I;\n                        end\n                    end\n                end\n\n                CHECK_RIGHT: begin\n                    if (k < captured_len) begin\n                        if ((captured_arr[k*8 +: 8] > captured_arr[i*8 +: 8]) &&\n                            (captured_arr[k*8 +: 8] > left_min_above)) begin\n                            right_found <= 1'b1;\n                            state <= FOUND_VALID;\n                        end else begin\n                            k <= k + 4'd1;\n                        end\n                    end else begin\n                        i <= i + 4'd1;\n                        state <= INIT_I;\n                    end\n                end\n\n                FOUND_VALID: begin\n                    result <= 1'b1;\n                    done <= 1'b1;\n                    state <= DONE_STATE;\n                end\n\n                DONE_STATE: begin\n                    if (!start) begin  // Wait for start to deassert\n                        done <= 1'b0;\n                        state <= IDLE;\n                    end\n                end\n\n                default: state <= IDLE;\n            endcase\n        end\n    end\n\nendmodule